/**
 * Unit tests for org.apache.commons.lang3.StringUtils.equals(CharSequence, CharSequence)
 */
public class StringUtils_equals_TriageGen2Test {







    @Test
    public void testEquals_ContentMismatch() {
        String str1 = "hello";
        String str2 = "world";
        String str3 = "hello ";
        // Covers: return cs1.equals(cs2);
        assertFalse("Should return false for different content", StringUtils.equals(str1, str2));
        assertFalse("Should return false for different length content", StringUtils.equals(str1, str3));
