/**
 * Unit tests for org.apache.commons.lang3.StringUtils.equals(CharSequence, CharSequence)
 */
public class StringUtils_equals_TriageGen2Test {









    @Test
    public void testEquals_EmptyStrings() {
        // Verifies edge cases of empty sequences
        assertTrue("Should return true for two empty strings", StringUtils.equals("", ""));
        assertTrue("Should return true for empty string and empty StringBuilder", StringUtils.equals("", new StringBuilder()));
        assertFalse("Should return false for empty and non-empty", StringUtils.equals("", " "));
    }
}
